    VPrint("Node4: initializing receiver\n");
    udpIpPg pUdp(4, NODE4_IPV4_ADDR, NODE4_MAC_ADDR, NODE4_UDP_PORT);
    pUdp.registerUsrRxCbFunc(rxCallback, nullptr);
    while (true) pUdp.UdpVpSendIdle(1);
}

