// --------------------------------------------
// Timescale
// --------------------------------------------

`timescale 1ps/1ps

// --------------------------------------------
// Definitions
// --------------------------------------------

`define TXD_ADDR                      32'h0
`define TXC_ADDR                      32'h1
`define TICKS_ADDR                    32'h2
`define HLT_ADDR                      32'h3

// ============================================
//  MODULE
// ============================================

module udp_ip_pg
#(parameter                            NODE    = 0)
(
  input                                clk,

  // GMII interface
  output reg  [7:0]                    txd,
  output reg                           txen,
  output reg                           txer,

  input       [7:0]                    rxd,
  input                                rxdv,
  input                                rxer,

  output reg                           halt
);

// --------------------------------------------
// Signal definitions
// --------------------------------------------

integer     count;

wire [31:0] nodenum = NODE;
wire [31:0] Addr;
wire        WE;
wire        RD;
wire [31:0] DataOut;
reg  [31:0] DataIn;
wire        Update;
reg         UpdateResponse;

// --------------------------------------------
// Continuous assignments
// --------------------------------------------

// Ensure there is no race on the update ordering on
// the rising edge of the clock between updating the
// inputs and the synchronous process below being called.

`ifndef VERILATOR

wire  [7:0] rxd_int;
wire  [1:0] rxc_int;

assign #1   rxd_int                    = rxd;
assign #1   rxc_int                    = {rxer, rxdv};

`else

reg   [7:0] rxd_int;
reg   [1:0] rxc_int;

always @(negedge clk)
begin
  rxd_int                              <= rxd;
  rxc_int                              <= {rxer, rxdv};
end

`endif

// --------------------------------------------
// Initialisation
// --------------------------------------------

initial
begin
  UpdateResponse                       = 1'b1;
  txd                                  = 8'h00;
  txen                                 = 1'b0;

  count                                = 0;
  halt                                 = 1'b0;
end

// --------------------------------------------
// Process to generate a tick count
// --------------------------------------------

always @(posedge clk)
begin
  count                                <= count + 1;
end

// --------------------------------------------
// Asynchronous process to access the ports and
// internal state.
// --------------------------------------------

always @(Update)
begin

  DataIn           = 32'h0;

  if (WE == 1'b1 || RD == 1'b1)
  begin
    case (Addr)

    // Update the TXD low word, if a write, and read the low RXD inputs
    `TXD_ADDR: begin
      DataIn                           = {24'h0, rxd_int};
      if (WE == 1'b1)
      begin
        txd                            = DataOut[7:0];
      end
    end
    // Update the TXC bits, if a write, and read the RXC inputs
    `TXC_ADDR: begin
      DataIn                           = {30'h0, rxc_int};
      if (WE == 1'b1)
      begin
        txen                           = DataOut[0];
        txer                           = DataOut[1];
      end
    end

    // This address must be accessed as a delta update since
    // it does not read the RX inputs
    `TICKS_ADDR: begin
      DataIn                           = count;
    end

    // It is recommended that this address is accessed as a delta
    // update in case a packet is being received and the sim does
    // not halt immediately. Assume it is a 'request' to halt to the
    // external logic.
    `HLT_ADDR: begin
      if (WE == 1'b1)
      begin
        halt                           = DataOut[0];
      end
    end

    // Only the above addresses are valid.
    default: begin
       $display("***ERROR: udp_ip_pg---access to invalid address from VProc");
       $finish;
    end
    endcase
  end

  // Acknowledge the access by inverting the response input to VProc
  UpdateResponse                       = ~UpdateResponse;
end

  // --------------------------------------------
  // Virtual Processor to run packet generation
  // software.
  // --------------------------------------------

  VProc vp (
   .Clk                                (clk),
   .Addr                               (Addr),

`ifdef VPROC_BYTE_ENABLE
   .BE                                 (),
`endif

   .WE                                 (WE),
   .RD                                 (RD),
   .DataOut                            (DataOut),
   .DataIn                             (DataIn),
   .WRAck                              (WE),
   .RDAck                              (RD),

`ifdef VPROC_BURST_IF
    // Burst count
    .Burst                             (),
    .BurstFirst                        (),
    .BurstLast                         (),
`endif

   .Interrupt                          (3'b000),
   .Update                             (Update),
   .UpdateResponse                     (UpdateResponse),
   .Node                               (nodenum[3:0])
  );

endmodule

